let data=load(),tab='home',month=today().slice(0,7),selectedCategory=null,expandedSub=null,incomeExpanded=false,calendarExpanded=false;
function load(){try{let a=JSON.parse(localStorage.getItem(KEY));if(a&&Array.isArray(a.transactions))return a}catch(e){}return{transactions:[],savings:1688.99,debts:Object.fromEntries(DEBTS.map(x=>[x[0],x[1]])),goal:11842,monthlyIncome:3591.01,monthlySavings:718.21,monthlyBudget:Object.fromEntries(CATS.map(x=>[x[0],x[1]])),financeLog:[]}}
function save(){localStorage.setItem(KEY,JSON.stringify(data))}
function migrate(){let changed=false;if(!Array.isArray(data.categories)){data.categories=CATS.map(([name,,icon])=>({name,icon}));changed=true}if(!data.monthOverrides){data.monthOverrides={};changed=true}if(!data.futureBudgets){data.futureBudgets=[];changed=true}if(!data.retirement){data.retirement={employee:35349,city:66784,asOf:'2026-11-13',a401:9090.99,a401Date:'2026-09-30',health:13698.27,healthDate:'2026-09-30',employeeRate:11.26,cityRate:21.13};changed=true}if(!Array.isArray(data.paychecks)){data.paychecks=[];changed=true}if(!Array.isArray(data.bills)){data.bills=[];changed=true}if(!data.rollovers){data.rollovers={};changed=true}if(!data.subcategories){data.subcategories={};changed=true}if(!Array.isArray(data.payrollYears)){data.payrollYears=PAYROLL_SEED.map(x=>({...x}));changed=true}if(Array.isArray(data.payrollYears)){const known={2021:1050,2022:1800,2023:750,2024:1800,2025:1800,2026:1500};for(const row of data.payrollYears){if(row.retirementHealthEmployer===undefined&&Object.prototype.hasOwnProperty.call(known,row.year)){row.retirementHealthEmployer=known[row.year];changed=true}}}if(!data.categoryStarts){data.categoryStarts={};for(const c of data.categories)data.categoryStarts[c.name]='2026-11';changed=true}if(!Array.isArray(data.savingsGoals)){data.savingsGoals=[];changed=true}if(changed)save()}
// Historical payroll summaries are data, not hard-coded financial calculations.
// 2026 is a YTD snapshot and must be replaced (not added) when a newer paystub arrives.
