{year:2021,date:'2021-12-30',gross:28002.72,net:19384.22,taxes:4803.69,employee:2913.77,city:7094.68,a401:541.17,taxable:24255.11,retirementHealthEmployer:1050.00,source:'Final paystub',partial:true},
{year:2022,date:'2022-12-30',gross:50716.15,net:37059.44,taxes:6676.71,employee:5234.96,city:12445.25,a401:1046.11,taxable:43865.75,retirementHealthEmployer:1800.00,source:'Final paystub'},
{year:2023,date:'2023-12-29',gross:56106.86,net:39408.03,taxes:8840.42,employee:5893.05,city:13368.45,a401:1154.71,taxable:48393.57,retirementHealthEmployer:750.00,source:'Final paystub'},
{year:2024,date:'2024-12-27',gross:59844.80,net:41230.06,taxes:10066.59,employee:6560.23,city:14099.67,a401:1273.00,taxable:51444.97,retirementHealthEmployer:1800.00,source:'Final paystub'},
{year:2025,date:'2025-12-26',gross:60546.11,net:41581.09,taxes:10005.85,employee:6807.09,city:13947.10,a401:1336.06,taxable:51737.42,retirementHealthEmployer:1800.00,source:'Final paystub'},
{year:2026,date:'2026-11-13',gross:54898.52,net:37805.14,taxes:8956.47,employee:6051.52,city:11807.37,a401:1244.92,taxable:46890.33,retirementHealthEmployer:1500.00,source:'YTD paystub',partial:true}
