migrate();
function payrollRows(){return [...data.payrollYears].sort((a,b)=>a.year-b.year)}
function payrollSum(field){return Math.round(payrollRows().reduce((sum,row)=>sum+Number(row[field]||0),0)*100)/100}
function totalCompensation(){return money(payrollSum('gross')+payrollSum('city')+payrollSum('a401')+payrollSum('retirementHealthEmployer'))}
function compensationChart(rows){let values=rows.map(r=>Number(r.net)||0),max=Math.max(1,...values);return `<div class="history-chart"><div class="chart-heading">Take-Home Pay by Year</div><div class="chart-bars">${rows.map(r=>`<div class="chart-column" title="${r.year}: ${fmt(r.net)}"><div class="chart-value">${fmt0(r.net)}</div><div class="chart-bar" style="height:${Math.max(4,Math.round(Number(r.net||0)/max*115))}px"></div><small>${r.year}</small></div>`).join('')}</div></div>`}
function payrollDashboard(){let rows=payrollRows(),ret=money(payrollSum('employee')+payrollSum('city')+payrollSum('a401')+payrollSum('retirementHealthEmployer'));return `<div class="sectionhead"><h2>Lifetime Compensation</h2></div><div class="card retirement-card"><div class="employer-label">City of Phoenix</div><button class="comp-toggle" id="compToggle" aria-expanded="${!!data.compExpanded}"><span>${fmt(totalCompensation())}</span><span class="comp-arrow">${data.compExpanded?'▴':'▾'}</span></button><div class="row earnings-row"><span>Take-Home Pay</span><b>${fmt(payrollSum('net'))}</b></div><div class="row earnings-row"><span>Taxes</span><b class="taxes-red">${fmt(payrollSum('taxes'))}</b></div><div class="row earnings-row"><span>Retirement Compensation</span><b>${fmt(ret)}</b></div>${data.compExpanded?`<div class="comp-expanded">${compensationChart(rows)}<button class="secondary update-payroll" id="payrollUpdate">Update YTD</button>${[...rows].reverse().map(r=>{let comp=money(Number(r.gross||0)+Number(r.city||0)+Number(r.a401||0)+Number(r.retirementHealthEmployer||0));return `<details class="annual-card"><summary><span><b>${r.year}${r.year===2021?' · Partial Year':r.year===new Date().getFullYear()?' · YTD':''}</b></span><span class="annual-amount"><b>${fmt(r.net)}</b><small>Take-Home Pay</small></span></summary><div class="row"><span>Total Compensation</span><b>${fmt(comp)}</b></div><div class="row"><span>Gross Wages</span><b>${fmt(r.gross)}</b></div><div class="row"><span>Taxes</span><b class="taxes-red">${fmt(r.taxes)}</b></div><div class="row"><span>Employee COPERS</span><b>${fmt(r.employee)}</b></div><div class="row"><span>City COPERS</span><b>${fmt(r.city)}</b></div><div class="row"><span>Employer 401(a)</span><b>${fmt(r.a401)}</b></div><div class="row"><span>Retirement Healthcare</span><b>${fmt(r.retirementHealthEmployer||0)}</b></div><div class="row"><span>Federal Taxable Wages</span><b>${fmt(r.taxable)}</b></div></details>`}).join('')}</div>`:''}</div>`}

function payrollEditor(){let y=Math.max(...data.payrollYears.map(r=>r.year)),r=data.payrollYears.find(x=>x.year===y);modal(`<h2>Update payroll year-to-date</h2><p class="note">Enter the YTD totals from your newest paystub. This replaces that year's previous snapshot and does not change your savings balance or record a new paycheck. Importing PDFs automatically is not enabled yet.</p><label class="field">Payroll year</label><input id="pyYear" type="number" min="2021" max="2100" value="${y}"><label class="field">Paystub date</label><input id="pyDate" type="date" value="${r.date}">${[['gross','YTD gross earnings'],['net','YTD net pay'],['taxes','YTD total taxes'],['taxable','YTD federal taxable gross'],['employee','YTD employee COPERS'],['city','YTD City COPERS'],['a401','YTD employer 401(a)'],['retirementHealthEmployer','YTD employer retirement healthcare contributions']].map(([k,label])=>`<label class="field">${label}</label><input id="py_${k}" type="number" min="0" step=".01" value="${r[k]??0}">`).join('')}<p id="pyError" class="note danger"></p><div class="btnrow"><button class="secondary" id="pyCancel">Cancel</button><button class="primary" id="pySave">Save snapshot</button></div>`);document.getElementById('pyCancel').onclick=close;document.getElementById('pyYear').onchange=()=>{let year=Number(document.getElementById('pyYear').value),row=data.payrollYears.find(x=>x.year===year);if(row){document.getElementById('pyDate').value=row.date;for(let k of ['gross','net','taxes','taxable','employee','city','a401','retirementHealthEmployer'])document.getElementById('py_'+k).value=row[k]}else{document.getElementById('pyDate').value=today();for(let k of ['gross','net','taxes','taxable','employee','city','a401','retirementHealthEmployer'])document.getElementById('py_'+k).value=''}};document.getElementById('pySave').onclick=()=>{let year=Number(document.getElementById('pyYear').value),date=document.getElementById('pyDate').value,fields={};for(let k of ['gross','net','taxes','taxable','employee','city','a401','retirementHealthEmployer']){let el=document.getElementById('py_'+k),n=Number(el.value);if(el.value.trim()===''||!Number.isFinite(n)||n<0){document.getElementById('pyError').textContent='Enter valid nonnegative YTD totals for every field.';return}fields[k]=Math.round(n*100)/100}if(!Number.isInteger(year)||year<2021||year>2100||!date||Number(date.slice(0,4))!==year||fields.net>fields.gross||fields.taxes>fields.gross){document.getElementById('pyError').textContent='Check the year, date, gross, net, and tax totals.';return}let old=data.payrollYears.find(x=>x.year===year);if(old&&date<old.date){document.getElementById('pyError').textContent='This is older than the stored snapshot. No changes were made.';return}data.payrollYears=data.payrollYears.filter(x=>x.year!==year);data.payrollYears.push({year,date,...fields,source:'Manually entered YTD paystub',partial:true});save();close();render()}}
const categories=()=>data.categories;
function getBudget(c,m=month){if(data.categoryStarts?.[c]&&m<data.categoryStarts[c])return 0;if(data.monthOverrides[m]&&Object.prototype.hasOwnProperty.call(data.monthOverrides[m],c))return Number(data.monthOverrides[m][c]);let future=data.futureBudgets.filter(x=>x.category===c&&x.start<=m).sort((a,b)=>b.start.localeCompare(a.start))[0];return Number(future?future.amount:(data.monthlyBudget[c]??0))}
const monthly=()=>data.transactions.filter(t=>t.date.slice(0,7)===month),spent=c=>monthly().filter(t=>t.category===c).reduce((s,t)=>s+t.amount,0),total=()=>monthly().reduce((s,t)=>s+t.amount,0),budget=()=>categories().reduce((s,c)=>s+getBudget(c.name),0);
function bar(spending,budgetAmount){let lo=Math.min(0,spending),hi=Math.max(0,budgetAmount,spending);if(hi===lo)return `<div class="mini"></div>`;let pct=v=>(v-lo)/(hi-lo)*100,limit=pct(Math.max(0,budgetAmount)),actual=pct(spending);if(spending<0)return `<div class="mini budget-track"><div class="budget-negative" style="width:${pct(0)}%"></div></div>`;let over=spending>budgetAmount&&budgetAmount>=0;return `<div class="mini budget-track"><div class="budget-blue" style="width:${Math.min(actual,limit)}%"></div>${over?`<div class="budget-excess" style="left:calc(${limit}% + 3px);width:calc(${100-limit}% - 3px);--overspend-intensity:${Math.min(1,Math.max(.25,(spending-budgetAmount)/Math.max(1,budgetAmount)))}"></div>`:''}</div>`}

function remainingColor(spending,b){if(b<=0)return spending>0?'rgb(245,105,111)':'rgb(168,240,182)';let ratio=(b-spending)/b;let neutral=[231,238,248],green=[90,214,143],red=[225,71,85],t=Math.min(1,Math.abs(ratio));let target=ratio>=0?green:red;return `rgb(${neutral.map((v,i)=>Math.round(v+(target[i]-v)*t)).join(',')})`}
function monthHeader(){let d=new Date(month+'-02T12:00:00');return `<div class="monthnav"><button data-month="-1" aria-label="Previous month">‹</button><button class="month-title" id="monthCalendar" aria-expanded="${calendarExpanded}">${d.toLocaleString('en-US',{month:'long',year:'numeric'})} ${calendarExpanded?'▴':'▾'}</button><button data-month="1" aria-label="Next month">›</button></div>`}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));document.getElementById('view').innerHTML=tab==='home'?home():tab==='history'?history():finances();bind()}
function home(){let t=total(),b=budget(),remaining=b-t,p=b?t/b*100:0,checks=monthPaychecks(month),actual=checks.filter(x=>x.actual).reduce((v,x)=>v+x.net,0),expected=checks.filter(x=>!x.actual).reduce((v,x)=>v+x.net,0);let days=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate(),now=today().slice(0,7)===month?new Date().getDate():month<today().slice(0,7)?days:0,daysLeft=Math.max(0,days-now);return `${monthHeader()}${calendarExpanded?inlineCalendar():''}<section class="hero"><button class="income-inline" id="trackerIncome" aria-expanded="${incomeExpanded}"><span><small>Take-Home Pay · ${checks.length} Paychecks</small><strong>${fmt(actual+expected)}</strong></span><span>⌄</span></button>${incomeExpanded?`<div class="income-details">${checks.map(x=>`<div class="row"><span>${esc(x.date)} · ${x.actual?'Actual':'Expected'}</span><b>${fmt(x.net)}</b></div>`).join('')}<button class="secondary" id="paycheckBtn">Record Paycheck</button></div>`:''}<div class="eyebrow">${remaining>=0?'Available to Spend':'Over Budget'}</div><h1>${fmt(Math.abs(remaining))}</h1><div class="muted">of ${fmt(b)} Monthly Living Expenses</div><div class="track"><div class="fill ${p>100?'over':p>80?'warn':''}" style="width:${Math.min(100,p)}%"></div></div><div class="split"><div><span class="muted">Spent</span><strong>${fmt(t)}</strong></div><div><span class="muted">${month===today().slice(0,7)?'Per Day Left':'Transactions'}</span><strong>${month===today().slice(0,7)?fmt(Math.max(0,remaining)/Math.max(1,daysLeft)):monthly().length}</strong></div></div></section><div class="sectionhead"><h2>Category Budgets</h2><span class="pill">${categories().length} Categories</span></div>${categories().map(({name:c,icon})=>categoryAccordion(c,icon)).join('')}${debtDashboard()}<p class="note">Debt payments are tracked separately from living expenses.</p>`}
function debtSchedule(name){let defaults={'OneMain':{amount:183.33,day:15},'Chase Freedom':{amount:75,day:1},'Upstart':{amount:170.13,day:6}};return {...(defaults[name]||{amount:0,day:1}),...(data.debtSchedules?.[name]||{})}}
function debtPayments(name){return (data.financeLog||[]).filter(x=>x.type==='debt'&&x.name===name&&x.date?.slice(0,7)===month).reduce((v,x)=>v+Number(x.paymentAmount??x.amount??0),0)}
function debtDashboard(){let names=Object.keys(data.debts).filter(n=>Number(data.debts[n])>0);if(!names.length)return '';let due=names.reduce((v,n)=>v+Math.min(Number(data.debts[n]),debtSchedule(n).amount),0),paid=names.reduce((v,n)=>v+debtPayments(n),0),remaining=Math.max(0,due-paid);return `<div class="sectionhead"><h2>Debt Payments</h2><span class="pill">${names.length} Accounts</span></div><section class="hero debt-hero"><div class="eyebrow">Remaining Payments</div><h1>${fmt(remaining)}</h1><div class="muted">of ${fmt(due)} Monthly Obligations</div><div class="track"><div class="fill" style="width:${due?Math.min(100,paid/due*100):100}%"></div></div><div class="split"><div><span class="muted">Paid This Month</span><strong>${fmt(paid)}</strong></div><div><span class="muted">Remaining</span><strong>${fmt(remaining)}</strong></div></div></section>${names.map(n=>{let scheduled=Math.min(Number(data.debts[n]),debtSchedule(n).amount),paid=debtPayments(n);return `<details class="card debt-account"><summary><span><b>${esc(n)}</b><small>Due Day ${debtSchedule(n).day} · ${paid>=scheduled?'Paid':'Scheduled'}</small></span><strong>${fmt(Math.max(0,scheduled-paid))} ▾</strong></summary><div class="row"><span>Monthly Payment</span><b>${fmt(scheduled)}</b></div><div class="row"><span>Paid</span><b>${fmt(paid)}</b></div><button class="secondary" data-debt-record="${esc(n)}">Record Payment</button></details>`}).join('')}`}
function recordDebtPayment(name){let expected=debtSchedule(name).amount;modal(`<h2>Record ${esc(name)} Payment</h2><label class="field">Payment Amount ($)</label><input id="debtPaymentAmount" type="number" min="0.01" step=".01" value="${expected}"><label class="field">Principal Reduction ($)</label><input id="debtPrincipal" type="number" min="0" step=".01" value="0"><p class="note">Enter the amount that reduced your balance, excluding interest and fees. If unknown, leave it at zero and update the balance later.</p><label class="field">Payment Date</label><input id="debtPaymentDate" type="date" value="${month===today().slice(0,7)?today():month+'-01'}"><p id="debtPaymentError" class="danger note"></p><div class="btnrow"><button class="secondary" id="cancel">Cancel</button><button class="primary" id="saveDebtPayment">Save Payment</button></div>`);document.getElementById('cancel').onclick=close;document.getElementById('saveDebtPayment').onclick=()=>{let amount=Number(document.getElementById('debtPaymentAmount').value),principal=Number(document.getElementById('debtPrincipal').value),date=document.getElementById('debtPaymentDate').value;if(!date||!Number.isFinite(amount)||amount<=0||!Number.isFinite(principal)||principal<0||principal>amount||principal>Number(data.debts[name])){document.getElementById('debtPaymentError').textContent='Check the payment, principal reduction and date.';return}data.debts[name]=money(Number(data.debts[name])-principal);data.financeLog.push({date,type:'debt',name,amount:money(principal),paymentAmount:money(amount)});month=date.slice(0,7);save();close();render()}}

function txRows(a){return a.length?[...a].sort((x,y)=>y.date.localeCompare(x.date)).map(t=>`<div class="row tx"><div><b>${esc(t.note||t.subcategory||t.category)}</b><small>${esc(t.date)}</small></div><div class="right"><b>${fmt(t.amount)}</b><small><button data-edit="${esc(t.id)}">Edit</button></small></div></div>`).join(''):'<p class="muted">No expenses this month.</p>'}
function categoryAccordion(c,icon){let a=monthly().filter(t=>t.category===c),b=getBudget(c),sum=spent(c),subs=data.subcategories[c]||[],open=selectedCategory===c;return `<div class="card category-wrap"><button class="cat-toggle" data-category="${esc(c)}" aria-expanded="${open}"><div class="symbol">${esc(icon)}</div><div class="catmain"><b>${esc(c)}</b><div class="muted">${fmt(sum)} of ${fmt(b)}</div></div><div class="amount" style="color:${remainingColor(sum,b)}">${fmt(b-sum)} <span class="chevron">${open?'▾':'▸'}</span></div></button>${bar(sum,b)}${open?`<div class="category-inside"><div class="rollover-detail">Annual Carryover <button class="rollover-info ${rolloverAmount(c)<0?'rollover-red':'rollover-green'}" data-roll-info="${esc(c)}">${rolloverAmount(c)>=0?'+':'−'}${fmt0(Math.abs(rolloverAmount(c)))}</button></div>${c==='Subscriptions'?'':`<button class="secondary add-inline" data-add-cat="${esc(c)}">＋ Add Expense</button>`}${subs.map(x=>{let sa=a.filter(t=>t.subcategory===x.name),opened=expandedSub===x.name;return `<div class="sub-wrap"><button class="sub-toggle" data-sub="${esc(x.name)}" aria-expanded="${opened}"><span>${subIcon(x.name)}</span><span class="sub-name">${esc(x.name)}</span><b>${fmt(sa.reduce((v,t)=>v+t.amount,0))}</b><span>${opened?'▾':'▸'}</span></button>${opened?`<div class="sub-inside"><button class="secondary add-inline" data-add-sub="${esc(x.name)}">＋ Add Expense</button>${txRows(sa)}</div>`:''}</div>`}).join('')}${c==='Subscriptions'?'<button class="secondary add-inline" id="addSubscription">＋ Add Subscription</button>':''}${subs.length?'<div class="subtle">Other transactions</div>':''}${txRows(a.filter(t=>!t.subcategory||!subs.some(x=>x.name===t.subcategory)))}</div>`:''}</div>`}
function subIcon(name){let icons={'Xbox Game Pass':'🎮','Netflix':'🎬','Amazon Prime':'📦','Peacock':'🦚','Spotify':'🎵','YouTube Premium':'▶️','Apple Music':'🎵','Disney+':'✨','Hulu':'📺'};let custom=data.subLogos?.[name];return custom?`<img class="sub-logo" src="${esc(custom)}" alt="">`:`<span class="sub-logo-fallback">${icons[name]||'🔁'}</span>`}
function emergencyGoal(){let first='2026-11',now=today().slice(0,7),actual=0,projected=0;for(let i=0;i<6;i++){let d=new Date(Number(first.slice(0,4)),Number(first.slice(5))-1+i,2),m=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;if(m<now){actual+=data.transactions.filter(t=>t.date.slice(0,7)===m).reduce((v,t)=>v+Number(t.amount),0)}else{projected+=categories().reduce((v,c)=>v+getBudget(c.name,m),0)}}if(now>'2027-04'){actual=0;projected=0;let d=new Date(Number(now.slice(0,4)),Number(now.slice(5))-1,2);for(let i=1;i<=6;i++){let k=new Date(d.getFullYear(),d.getMonth()-i,2),m=`${k.getFullYear()}-${String(k.getMonth()+1).padStart(2,'0')}`;actual+=data.transactions.filter(t=>t.date.slice(0,7)===m).reduce((v,t)=>v+Number(t.amount),0)}}return money(actual+projected+1000)}

function rolloverAmount(c){let current=today().slice(0,7),end=month>current?current:month,year=month.slice(0,4),start=data.categoryStarts?.[c]||'2026-11';start=start>year+'-01'?start:year+'-01';if(end<start)return 0;let d=new Date(start+'-02T12:00:00'),limit=new Date(end+'-02T12:00:00'),sum=0;while(d<=limit){let m=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;sum+=getBudget(c,m)-data.transactions.filter(t=>t.category===c&&t.date.slice(0,7)===m&&t.date<=today()).reduce((a,t)=>a+Number(t.amount),0);d.setMonth(d.getMonth()+1)}return money(sum)}
function rolloverBadge(c){let v=rolloverAmount(c);return `<span class="rollover-corner ${v<0?'rollover-red':'rollover-green'}" aria-label="Year-to-date budget balance ${fmt(v)}">${v>=0?'+':'−'}${fmt0(Math.abs(v))}</span>`}

function categoryDetail(){let c=selectedCategory,a=monthly().filter(t=>t.category===c).sort((x,y)=>y.date.localeCompare(x.date)),b=getBudget(c);return `${monthHeader()}<button class="secondary" id="backCategory">← All categories</button><h2 style="margin:18px 0">${esc(c)}</h2><div class="card"><div class="row"><span>Monthly budget</span><b>${fmt(b)}</b></div><div class="row"><span>Spent</span><b>${fmt(spent(c))}</b></div><div class="row"><span>Remaining</span><b>${fmt(b-spent(c))}</b></div><div class="row"><span>Annual Running Balance</span><b>${fmt(rolloverAmount(c))}</b></div></div><button class="action" id="addCategoryExpense">＋ Add ${esc(c)} expense</button><div class="sectionhead"><h2>Transactions</h2><span class="pill">${a.length}</span></div><div class="card">${a.length?a.map(t=>`<div class="row tx"><div><b>${esc(t.note||t.subcategory||c)}</b><small>${esc(t.date)}${t.subcategory?' · '+esc(t.subcategory):''}</small></div><div class="right"><b>${fmt(t.amount)}</b><small><button data-edit="${esc(t.id)}">Edit</button></small></div></div>`).join(''):'<p class="muted">No expenses this month.</p>'}</div>`}
function history(){let a=[...monthly()].sort((x,y)=>y.date.localeCompare(x.date)||y.created-x.created);return `${monthHeader()}<div class="sectionhead"><h2>Transactions</h2><span class="pill">${a.length} entries</span></div><button class="action" id="addBtn">＋ Add Expense</button><div class="card">${a.length?a.map(t=>`<div class="row tx"><div><strong>${esc(t.category)}</strong><small>${esc(t.date)}${t.subcategory?' · '+esc(t.subcategory):''}${t.note?' · '+esc(t.note):''}</small></div><div class="right"><strong>${fmt(t.amount)}</strong><small><button data-edit="${esc(t.id)}">Edit</button></small></div></div>`).join(''):'<div class="empty">No transactions yet.<br>Add your first expense to start tracking.</div>'}</div><div class="row"><span class="muted">Total spending</span><b>${fmt(total())}</b></div>`}
function savingsAllocations(){let total=Math.max(0,Number(data.savings)||0),custom=(data.savingsGoals||[]).reduce((n,g)=>n+Math.max(0,Number(g.allocated)||0),0),emergency=Math.min(1000,total),reserve=Math.max(0,total-emergency-custom);return {total,emergency,reserve,custom,unallocated:Math.max(0,total-emergency-reserve-custom)}}
function goalProgress(name,amount,target){let p=target?Math.min(100,amount/target*100):0;return `<div class="savings-goal"><div class="row"><b>${esc(name)}</b><strong>${fmt(amount)}</strong></div><div class="row muted savings-meta"><span>${target?fmt(target)+' Goal':'No Target'}</span><span>${target?Math.round(p)+'%':''}</span></div>${target?`<div class="track"><div class="fill" style="width:${p}%"></div></div>`:''}</div>`}
function monthPaychecks(m){let y=Number(m.slice(0,4)),mo=Number(m.slice(5)),days=new Date(y,mo,0).getDate(),anchor=data.paySchedule?.anchor||'2026-11-13',frequency=data.paySchedule?.frequency||'biweekly',amount=Number(data.paySchedule?.net)||1657.39;let dates=[];for(let d=1;d<=days;d++){let date=`${m}-${String(d).padStart(2,'0')}`,delta=Math.round((new Date(date+'T12:00:00')-new Date(anchor+'T12:00:00'))/86400000);if(frequency==='biweekly'&&delta%14===0)dates.push(date)}return dates.map(date=>({date,net:Number(data.paychecks.find(p=>p.date===date)?.net??amount),actual:!!data.paychecks.find(p=>p.date===date)}))}
function monthIncome(m){return money(monthPaychecks(m).reduce((v,p)=>v+p.net,0))}
function finances(){let debts=Object.entries(data.debts),sum=debts.reduce((v,[,n])=>v+Number(n),0),a=savingsAllocations(),reserveTarget=Math.max(0,emergencyGoal()-1000);return `<div class="eyebrow">Your Financial Plan</div><h1 class="finance-title">Financial Snapshot</h1><div class="card snapshot-grid"><button id="incomeToggle" class="snapshot-cell"><small>${prettyMonth(month)} Take-Home Pay ▾</small><strong>${fmt(monthIncome(month))}</strong></button><div class="snapshot-cell"><small>Monthly Budget</small><strong>${fmt(budget())}</strong></div><button class="snapshot-cell" data-jump="debtSection"><small>Outstanding Debt ↘</small><strong>${fmt(sum)}</strong></button><button class="snapshot-cell" data-jump="savingsSection"><small>Liquid Savings ↘</small><strong>${fmt(data.savings)}</strong></button></div>${incomeExpanded?`<div class="card"><button class="action" id="paycheckBtn">＋ Add Paycheck</button><div class="sectionhead"><h3>Paycheck History</h3></div>${[...data.paychecks].sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<div class="row"><span>${esc(p.date)} · ${fmt(p.net)} Net</span><button class="secondary" data-pay-edit="${esc(p.id)}">Edit</button></div>`).join('')||'<p class="muted">No individual paychecks recorded yet.</p>'}</div>`:''}<div id="savingsSection" class="sectionhead"><h2>Liquid Savings</h2><button class="pill" id="savingsBtn" style="border:0;color:#e7f3ff">Update Balance</button></div><div class="card"><div class="row savings-total"><span>Total Savings</span><strong>${fmt(a.total)}</strong></div>${goalProgress('Emergency Fund',a.emergency,1000)}${goalProgress('Six-Month Reserve',a.reserve,reserveTarget)}${(data.savingsGoals||[]).map(g=>`<div class="goal-custom">${goalProgress(g.name,Number(g.allocated)||0,Number(g.target)||0)}<button class="secondary" data-goal-edit="${esc(g.id)}">Edit</button></div>`).join('')}<button class="secondary add-goal" id="addGoal">＋ Add Savings Goal</button></div><div id="debtSection" class="sectionhead"><h2>Outstanding Debt</h2><span class="pill">${fmt(sum)}</span></div>${debts.map(([n,v])=>`<div class="card row"><div><b>${esc(n)}</b><div class="muted" style="font-size:12px">${DEBTS.find(d=>d[0]===n)?.[2]||0}% APR</div></div><div style="text-align:right"><b>${fmt(v)}</b><div><button class="secondary" data-debt="${esc(n)}" style="padding:7px 10px;margin-top:7px;font-size:12px">Record Payment</button></div></div></div>`).join('')}${retirementPanel()}${payrollDashboard()}<button class="secondary" id="backupBtn" style="width:100%;margin:10px 0">Export Backup</button><button class="secondary" id="restoreBtn" style="width:100%">Restore Backup</button>`}
function savingsGoalEditor(id){let old=(data.savingsGoals||[]).find(g=>g.id===id),a=savingsAllocations(),available=a.reserve+(old?Number(old.allocated)||0:0);modal(`<h2>${old?'Edit':'Add'} Savings Goal</h2><label class="field">Goal Name</label><input id="goalName" maxlength="48" value="${esc(old?.name||'')}" placeholder="Vacation, Car, Education…"><label class="field">Target Amount (Optional)</label><input id="goalTarget" type="number" min="0" step=".01" value="${old?.target||''}"><label class="field">Savings Allocated</label><input id="goalAmount" type="number" min="0" step=".01" value="${old?.allocated||0}"><p class="subtle">Available From Six-Month Reserve: ${fmt(available)}</p><p id="goalError" class="danger note"></p><div class="btnrow">${old?'<button class="secondary" id="deleteGoal">Delete</button>':''}<button class="secondary" id="cancelGoal">Cancel</button><button class="primary" id="saveGoal">Save Goal</button></div>`);document.getElementById('cancelGoal').onclick=close;document.getElementById('deleteGoal')?.addEventListener('click',()=>{data.savingsGoals=data.savingsGoals.filter(g=>g.id!==id);save();close();render()});document.getElementById('saveGoal').onclick=()=>{let name=document.getElementById('goalName').value.trim(),target=Number(document.getElementById('goalTarget').value||0),allocated=Number(document.getElementById('goalAmount').value);if(!name||!Number.isFinite(target)||target<0||!Number.isFinite(allocated)||allocated<0||allocated>available+.001||(data.savingsGoals||[]).some(g=>g.id!==id&&g.name.toLowerCase()===name.toLowerCase())){document.getElementById('goalError').textContent='Enter a unique name and valid amounts within available savings.';return}if(old)Object.assign(old,{name,target:money(target),allocated:money(allocated)});else data.savingsGoals.push({id:String(Date.now()),name,target:money(target),allocated:money(allocated)});save();close();render()}}

function bind(){document.getElementById('payrollUpdate')?.addEventListener('click',payrollEditor);document.getElementById('compToggle')?.addEventListener('click',()=>{data.compExpanded=!data.compExpanded;save();render()});document.getElementById('monthCalendar')?.addEventListener('click',()=>{calendarExpanded=!calendarExpanded;render()});document.getElementById('addSubscription')?.addEventListener('click',newSubscription);document.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{let d=new Date(month+'-02T12:00:00');d.setMonth(d.getMonth()+Number(b.dataset.month));month=d.toISOString().slice(0,7);render()});document.getElementById('trackerIncome')?.addEventListener('click',()=>{incomeExpanded=!incomeExpanded;render()});document.querySelectorAll('[data-roll-info]').forEach(b=>b.onclick=()=>modal('<h2>Annual Budget Balance</h2><p>Your running budget surplus or deficit for this category this calendar year, or since the category was created. Resets every January 1.</p>'));document.querySelectorAll('[data-debt-record]').forEach(b=>b.onclick=()=>recordDebtPayment(b.dataset.debtRecord));document.getElementById('addBtn')?.addEventListener('click',()=>expense());document.querySelectorAll('.category-wrap').forEach(card=>card.addEventListener('click',e=>{if(e.target.closest('.category-inside'))return;const btn=card.querySelector('[data-category]');if(!btn)return;selectedCategory=selectedCategory===btn.dataset.category?null:btn.dataset.category;expandedSub=null;render()}));document.getElementById('backCategory')?.addEventListener('click',()=>{selectedCategory=null;render()});document.querySelectorAll('[data-add-cat]').forEach(b=>b.onclick=()=>expense(null,b.dataset.addCat));document.querySelectorAll('[data-sub]').forEach(b=>b.onclick=()=>{expandedSub=expandedSub===b.dataset.sub?null:b.dataset.sub;render()});document.querySelectorAll('[data-add-sub]').forEach(b=>b.onclick=()=>expense(null,selectedCategory,b.dataset.addSub));document.getElementById('manageSubLogos')?.addEventListener('click',()=>subscriptionSetup((data.subcategories.Subscriptions||[]).map(x=>x.name),0));document.getElementById('incomeToggle')?.addEventListener('click',()=>{incomeExpanded=!incomeExpanded;render()});document.querySelectorAll('[data-ret-detail]').forEach(b=>b.onclick=()=>retirementDetail(b.dataset.retDetail));document.getElementById('paycheckBtn')?.addEventListener('click',paycheckEditor);document.getElementById('retirementBtn')?.addEventListener('click',retirementEditor);document.getElementById('calendarBtn')?.addEventListener('click',calendarView);document.querySelectorAll('[data-pay-edit]').forEach(b=>b.onclick=()=>paycheckEditor(b.dataset.payEdit));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>expense(data.transactions.find(t=>t.id===b.dataset.edit)));document.querySelectorAll('[data-debt]').forEach(b=>b.onclick=()=>debt(b.dataset.debt));document.getElementById('savingsBtn')?.addEventListener('click',savings);document.getElementById('addGoal')?.addEventListener('click',()=>savingsGoalEditor());document.querySelectorAll('[data-goal-edit]').forEach(b=>b.onclick=()=>savingsGoalEditor(b.dataset.goalEdit));document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.jump)?.scrollIntoView({behavior:'smooth',block:'start'}));document.getElementById('backupBtn')?.addEventListener('click',backup);document.getElementById('restoreBtn')?.addEventListener('click',restore)}
function modal(html){document.getElementById('modalBody').innerHTML=html;document.getElementById('modal').hidden=false;document.querySelector('.sheet').scrollTop=0}function close(){document.getElementById('modal').hidden=true;document.querySelector('.sheet').style.transform='';document.querySelector('.sheet').style.transition=''}document.querySelector('[data-close]').onclick=close;document.getElementById('settingsBtn').onclick=settings;
function settings(){modal(`<h2>Manage Categories</h2><div class="modal-month">${prettyMonth(month)} <span aria-hidden="true">🔒</span></div>${categories().map((c,i)=>`<div class="card row reorder-item" data-category-index="${i}"><button class="reorder-grip" aria-label="Drag to reorder ${esc(c.name)}" title="Drag to reorder">☰</button><div class="reorder-label"><b>${esc(c.icon)} ${esc(c.name)}</b><div class="muted">${fmt(getBudget(c.name))}</div></div><button class="secondary" data-cat-edit="${i}">Edit</button></div>`).join('')}<button class="action" id="newCat">＋ Add Category</button><button class="secondary" id="manageRecurring" style="width:100%;margin-top:12px">Recurring Payments & Logos</button><button class="secondary" id="resetBudgets" style="width:100%">Restore Original Budgets</button>`);document.querySelectorAll('[data-cat-edit]').forEach(b=>b.onclick=()=>categoryEditor(Number(b.dataset.catEdit)));document.getElementById('newCat').onclick=()=>categoryEditor(-1);document.getElementById('manageRecurring').onclick=billsEditor;enableCategoryReordering();document.getElementById('resetBudgets').onclick=()=>{modal(`<h2>Restore Budgets?</h2><div class="modal-month">${prettyMonth(month)}</div><div class="btnrow"><button class="secondary" id="no">Cancel</button><button class="primary" id="yes">Restore This Month</button></div>`);document.getElementById('no').onclick=settings;document.getElementById('yes').onclick=()=>{data.monthOverrides[month]=Object.fromEntries(CATS.filter(([n])=>categories().some(c=>c.name===n)).map(([n,v])=>[n,v]));save();settings();render()}}}

function categoryEditor(i){let old=i>=0?categories()[i]:null;modal(`<h2>${old?'Edit':'Add'} Category</h2><div class="modal-month">${prettyMonth(month)} <span aria-hidden="true">🔒</span></div><label class="field">Category Name</label><input id="catName" maxlength="45" value="${esc(old?.name??'')}" placeholder="Category name"><label class="field">Icon (Emoji)</label><input id="catIcon" maxlength="8" value="${esc(old?.icon??'🧾')}"><label class="field">Monthly Budget ($)</label><input id="catBudget" type="number" min="0" step="0.01" inputmode="decimal" value="${old?getBudget(old.name).toFixed(2):'0.00'}"><label class="field">Apply Budget Change</label><select id="scope"><option value="month" ${old?'selected':''}>This Month Only</option><option value="future" ${old?'':'selected'}>This Month & All Future Months</option></select><p id="catError" class="danger note"></p><div class="btnrow"><button class="secondary" id="cancel">Cancel</button><button class="primary" id="saveCat">Save</button></div>${old?'<button class="secondary" id="editSubs" style="width:100%;margin-top:12px">Manage Subcategories</button><button class="secondary danger" id="deleteCat" style="width:100%;margin-top:12px">Delete Category</button>':''}`);document.getElementById('cancel').onclick=settings;if(old)document.getElementById('editSubs').onclick=()=>subcategoryEditor(old.name);document.getElementById('saveCat').onclick=()=>{let name=document.getElementById('catName').value.trim(),icon=document.getElementById('catIcon').value.trim()||'🧾',raw=document.getElementById('catBudget').value,amount=Number(raw),scope=document.getElementById('scope').value,error=document.getElementById('catError');if(!name||!raw||!Number.isFinite(amount)||amount<0){error.textContent='Enter a name and a valid nonnegative budget.';return}if(categories().some((c,j)=>j!==i&&c.name.toLowerCase()===name.toLowerCase())){error.textContent='A category with that name already exists.';return}amount=Math.round(amount*100)/100;if(old&&name!==old.name){data.transactions.forEach(t=>{if(t.category===old.name)t.category=name});if(Object.prototype.hasOwnProperty.call(data.monthlyBudget,old.name)){data.monthlyBudget[name]=data.monthlyBudget[old.name];delete data.monthlyBudget[old.name]}Object.values(data.monthOverrides).forEach(o=>{if(Object.prototype.hasOwnProperty.call(o,old.name)){o[name]=o[old.name];delete o[old.name]}});data.futureBudgets.forEach(x=>{if(x.category===old.name)x.category=name});if(data.categoryStarts?.[old.name]){data.categoryStarts[name]=data.categoryStarts[old.name];delete data.categoryStarts[old.name]}}if(old){categories()[i]={name,icon}}else{categories().push({name,icon});data.monthlyBudget[name]=0;data.categoryStarts??={};data.categoryStarts[name]=month}if(scope==='month'&&old){data.monthOverrides[month]??={};data.monthOverrides[month][name]=amount}else{data.futureBudgets=data.futureBudgets.filter(x=>!(x.category===name&&x.start===month));data.futureBudgets.push({category:name,start:month,amount});if(data.monthOverrides[month])delete data.monthOverrides[month][name]}save();settings();render()};if(old)document.getElementById('deleteCat').onclick=()=>{if(data.transactions.some(t=>t.category===old.name)){document.getElementById('catError').textContent='This category has transactions. Rename it instead so no history is lost.';return}categories().splice(i,1);delete data.monthlyBudget[old.name];if(data.categoryStarts)delete data.categoryStarts[old.name];Object.values(data.monthOverrides).forEach(o=>delete o[old.name]);data.futureBudgets=data.futureBudgets.filter(x=>x.category!==old.name);save();settings();render()}}

function expense(t,preset,presetSub){let edit=!!t,opts=categories().map(({name:n})=>`<option value="${esc(n)}" ${(t?.category||preset)===n?'selected':''}>${n}</option>`).join('');modal(`<h2>${edit?'Edit':'Add'} expense</h2><form id="expenseForm"><label class="field">Amount ($)</label><input id="amt" type="number" inputmode="decimal" min="0.01" step="0.01" required placeholder="0.00" value="${t?.amount??''}"><label class="field">Category</label><select id="cat">${opts}</select><label class="field">Subcategory (optional)</label><select id="subcat"></select><label class="field">Date</label><input id="date" type="date" required value="${t?.date??today()}"><label class="field">Note (optional)</label><input id="note" maxlength="140" placeholder="Where did you spend it?" value="${esc(t?.note??'')}"><div class="btnrow"><button type="button" class="secondary" id="cancel">Cancel</button><button class="primary">${edit?'Save changes':'Save expense'}</button></div>${edit?'<button type="button" class="secondary danger" id="delete" style="width:100%;margin-top:12px">Delete expense</button>':''}</form>`);const updateSubs=()=>{let c=document.getElementById('cat').value;document.getElementById('subcat').innerHTML='<option value="">None</option>'+(data.subcategories[c]||[]).map(x=>`<option value="${esc(x.name)}" ${(t?.subcategory||presetSub)===x.name?'selected':''}>${esc(x.name)}${x.budget?' · '+fmt(x.budget):''}</option>`).join('')};document.getElementById('cat').onchange=updateSubs;updateSubs();document.getElementById('cancel').onclick=close;document.getElementById('expenseForm').onsubmit=e=>{e.preventDefault();let amount=Number(document.getElementById('amt').value);if(!Number.isFinite(amount)||amount<=0)return;let entry={id:t?.id??(crypto.randomUUID?crypto.randomUUID():String(Date.now())),created:t?.created??Date.now(),amount:Math.round(amount*100)/100,category:document.getElementById('cat').value,subcategory:document.getElementById('subcat').value,date:document.getElementById('date').value,note:document.getElementById('note').value.trim()};if(edit)data.transactions=data.transactions.map(x=>x.id===t.id?entry:x);else data.transactions.push(entry);month=entry.date.slice(0,7);save();close();render()};if(edit)document.getElementById('delete').onclick=()=>{data.transactions=data.transactions.filter(x=>x.id!==t.id);save();close();render()}}
function savings(){modal(`<h2>Update savings</h2><p class="note">Enter a deposit (positive) or withdrawal (negative). This doesn't count as spending.</p><label class="field">Change in savings ($)</label><input id="change" type="number" step="0.01" inputmode="decimal" placeholder="331.48"><div class="btnrow"><button class="secondary" id="cancel">Cancel</button><button class="primary" id="apply">Apply</button></div>`);document.getElementById('cancel').onclick=close;document.getElementById('apply').onclick=()=>{let n=Number(document.getElementById('change').value);if(!Number.isFinite(n)||!document.getElementById('change').value)return;if(data.savings+n<0)return;data.savings=Math.round((data.savings+n)*100)/100;let room=Math.max(0,data.savings-1000),allocated=(data.savingsGoals||[]).reduce((v,g)=>v+Number(g.allocated||0),0);if(allocated>room){let factor=allocated?room/allocated:0;for(let g of data.savingsGoals)g.allocated=money(Number(g.allocated||0)*factor);let excess=money(data.savingsGoals.reduce((v,g)=>v+Number(g.allocated||0),0)-room);if(excess>0&&data.savingsGoals.length)data.savingsGoals[0].allocated=money(data.savingsGoals[0].allocated-excess)}data.financeLog.push({date:today(),type:'savings',amount:n});save();close();render()}}
function debt(name){modal(`<h2>${esc(name)} payment</h2><p class="note">Enter how much your loan or card balance actually decreased (principal reduction). Interest and fees aren't calculated automatically.</p><label class="field">Principal reduction ($)</label><input id="change" type="number" min="0" step="0.01" inputmode="decimal" placeholder="0.00"><div class="btnrow"><button class="secondary" id="cancel">Cancel</button><button class="primary" id="apply">Apply</button></div>`);document.getElementById('cancel').onclick=close;document.getElementById('apply').onclick=()=>{let n=Number(document.getElementById('change').value);if(!Number.isFinite(n)||n<=0)return;data.debts[name]=Math.max(0,Math.round((data.debts[name]-n)*100)/100);data.financeLog.push({date:today(),type:'debt',name,amount:n});save();close();render()}}
function backup(){let blob=new Blob([JSON.stringify({app:'Spendwise',version:1,exportedAt:new Date().toISOString(),data},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`spendwise-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){modal(`<h2>Restore backup</h2><p class="note">Restoring replaces the data currently saved on this phone. Export a backup first if you want to keep it.</p><input type="file" id="file" accept="application/json,.json"><div class="btnrow"><button class="secondary" id="cancel">Cancel</button><button class="primary" id="import">Restore</button></div><p id="error" class="danger note"></p>`);document.getElementById('cancel').onclick=close;document.getElementById('import').onclick=async()=>{try{let f=document.getElementById('file').files[0];if(!f)throw Error('Choose a backup file.');let v=JSON.parse(await f.text());if(v.app!=='Spendwise'||!v.data||!Array.isArray(v.data.transactions)||!v.data.monthlyBudget||!v.data.debts)throw Error('This is not a valid Spendwise backup.');data=v.data;migrate();save();close();render()}catch(e){document.getElementById('error').textContent=e.message}}}

// iPhone-safe category sorting: listen on document so moving DOM rows cannot lose the gesture.
function enableCategoryReordering(){
  const sheet=document.querySelector('.sheet');
  const list=[...document.querySelectorAll('.reorder-item')];
  list.forEach(item=>{
    const grip=item.querySelector('.reorder-grip');
    grip.addEventListener('touchstart',startTouch,{passive:false});
    grip.addEventListener('pointerdown',startMouse);
    function startTouch(e){
      if(e.touches.length!==1)return;
      e.preventDefault();
      begin(e.touches[0].clientY,'touch',e.touches[0].identifier);
    }
    function startMouse(e){
      if(e.pointerType==='touch'||e.button!==0)return;
      e.preventDefault();
      begin(e.clientY,'mouse',e.pointerId);
    }
    function begin(startY,kind,id){
      if(document.querySelector('.reorder-ghost'))return;
      const rect=item.getBoundingClientRect();
      const placeholder=document.createElement('div');
      placeholder.className='reorder-placeholder';
      placeholder.style.height=rect.height+'px';
      placeholder.style.marginBottom=getComputedStyle(item).marginBottom;
      item.before(placeholder);
      const ghost=item.cloneNode(true);
      ghost.classList.add('reorder-ghost','reordering');
      ghost.removeAttribute('data-category-index');
      ghost.style.cssText=`position:fixed;z-index:30;pointer-events:none;left:${rect.left}px;top:${rect.top}px;width:${rect.width}px;height:${rect.height}px;margin:0;`;
      document.body.appendChild(ghost);
      item.style.display='none';
      const offset=startY-rect.top;
      let lastY=startY,active=true,scrollTimer=null;
      function position(y){
        lastY=y;
        ghost.style.top=(y-offset)+'px';
        const candidates=[...document.querySelectorAll('.reorder-item')].filter(r=>r!==item);
        const target=candidates.find(r=>y<r.getBoundingClientRect().top+r.getBoundingClientRect().height/2);
        if(target)target.before(placeholder);
        else if(candidates.length)candidates[candidates.length-1].after(placeholder);
      }
      function autoScroll(){
        if(!active)return;
        const r=sheet.getBoundingClientRect();
        if(lastY>r.bottom-65)sheet.scrollTop+=Math.min(18,(lastY-(r.bottom-65))*.55+3);
        else if(lastY<r.top+85)sheet.scrollTop-=Math.min(18,((r.top+85)-lastY)*.55+3);
        position(lastY);
        scrollTimer=requestAnimationFrame(autoScroll);
      }
      function onTouchMove(e){
        const t=[...e.changedTouches].find(t=>t.identifier===id);
        if(!t)return;
        e.preventDefault();position(t.clientY);
      }
      function onPointerMove(e){if(e.pointerId===id){e.preventDefault();position(e.clientY)}}
      function onTouchEnd(e){if([...e.changedTouches].some(t=>t.identifier===id))finish(false)}
      function onTouchCancel(e){if([...e.changedTouches].some(t=>t.identifier===id))finish(true)}
      function onPointerEnd(e){if(e.pointerId===id)finish(e.type==='pointercancel')}
      function finish(cancel){
        if(!active)return;
        active=false;cancelAnimationFrame(scrollTimer);
        document.removeEventListener('touchmove',onTouchMove);
        document.removeEventListener('touchend',onTouchEnd);
        document.removeEventListener('touchcancel',onTouchCancel);
        document.removeEventListener('pointermove',onPointerMove);
        document.removeEventListener('pointerup',onPointerEnd);
        document.removeEventListener('pointercancel',onPointerEnd);
        if(!cancel)placeholder.replaceWith(item);
        else placeholder.remove();
        item.style.display='';ghost.remove();
        if(cancel)return;
        const reordered=[...document.querySelectorAll('.reorder-item')].map(r=>categories()[Number(r.dataset.categoryIndex)]);
        if(reordered.length===categories().length){data.categories=reordered;save();settings();render()}
      }
      if(kind==='touch'){
        document.addEventListener('touchmove',onTouchMove,{passive:false});
        document.addEventListener('touchend',onTouchEnd);
        document.addEventListener('touchcancel',onTouchCancel);
      }else{
        document.addEventListener('pointermove',onPointerMove,{passive:false});
        document.addEventListener('pointerup',onPointerEnd);
        document.addEventListener('pointercancel',onPointerEnd);
      }
      scrollTimer=requestAnimationFrame(autoScroll);
    }
  });
}
// The top handle dismisses any modal without interfering with scrolling inside it.
(()=>{const handle=document.querySelector('.handle'),sheet=document.querySelector('.sheet');
  handle.addEventListener('pointerdown',e=>{
    if(e.button!==0&&e.pointerType==='mouse')return;
    const start=e.clientY;let offset=0;
    handle.setPointerCapture(e.pointerId);
    const move=ev=>{offset=Math.max(0,ev.clientY-start);sheet.style.transition='none';sheet.style.transform=`translateY(${offset}px)`};
    const finish=()=>{cleanup();sheet.style.transition='transform 180ms ease';if(offset>85){close()}else{sheet.style.transform='';setTimeout(()=>sheet.style.transition='',200)}};
    const cancel=()=>{cleanup();sheet.style.transform='';sheet.style.transition=''};
    const cleanup=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',finish);handle.removeEventListener('pointercancel',cancel)};
    handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',finish);handle.addEventListener('pointercancel',cancel);
  });
  handle.addEventListener('keydown',e=>{if(e.key==='Escape'||e.key==='Enter'||e.key===' '){e.preventDefault();close()}});
})();
