function recurringEditor(i){
  let b=i>=0?data.bills[i]:null,cat=b?.category||(data.subcategories?.Subscriptions?.some(x=>x.name===b?.name)?'Subscriptions':'Other Living Expenses');
  const cats=categories().map(x=>`<option value="${esc(x.name)}" ${x.name===cat?'selected':''}>${esc(x.name)}</option>`).join('');
  modal(`<h2>${b?'Edit':'Add'} Recurring Payment</h2><label class="field">Company or bill name</label><input id="recName" maxlength="70" value="${esc(b?.name||'')}" placeholder="e.g. Verizon, Progressive"><label class="field">Expense category</label><select id="recCategory">${cats}</select><label class="field">First scheduled date</label><input id="recDate" type="date" value="${esc(b?.date||`${month}-${String(b?.day||1).padStart(2,'0')}`)}"><label class="field">Frequency</label><select id="recFrequency"><option value="monthly" ${b?.frequency!=='yearly'?'selected':''}>Monthly</option><option value="yearly" ${b?.frequency==='yearly'?'selected':''}>Yearly</option></select><label class="field">Expected amount ($)</label><input id="recAmount" type="number" min="0" step=".01" inputmode="decimal" value="${b?.amount??''}"><label class="field">Company logo (optional)</label><input id="recLogo" type="file" accept="image/png,image/jpeg,image/webp"><p class="note">Existing subscription logos are retained. New logos appear on the calendar and are stored on this device.</p><p id="recError" class="danger note"></p><div class="btnrow"><button class="secondary" id="recCancel">Cancel</button><button class="primary" id="recSave">Save</button></div>${b?'<button class="secondary danger" id="recDelete" style="width:100%;margin-top:12px">Remove reminder</button>':''}`);
  document.getElementById('recCancel').onclick=billsEditor;
  if(b)document.getElementById('recDelete').onclick=()=>{data.bills.splice(i,1);save();render();billsEditor()};
  document.getElementById('recSave').onclick=async()=>{
    const name=document.getElementById('recName').value.trim(),date=document.getElementById('recDate').value,amountText=document.getElementById('recAmount').value,amount=Number(amountText),frequency=document.getElementById('recFrequency').value,category=document.getElementById('recCategory').value,err=document.getElementById('recError');
    if(!name||!/^\d{4}-\d{2}-\d{2}$/.test(date)||!amountText||!Number.isFinite(amount)||amount<0){err.textContent='Enter a name, valid date, and expected amount.';return}
    const file=document.getElementById('recLogo').files[0];let logo=null;
    if(file){if(file.size>2000000){err.textContent='Choose an image under 2 MB.';return}try{const img=new Image(),url=URL.createObjectURL(file);try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});const canvas=document.createElement('canvas');canvas.width=80;canvas.height=80;canvas.getContext('2d').drawImage(img,0,0,80,80);logo=canvas.toDataURL('image/png')}finally{URL.revokeObjectURL(url)}}catch(e){err.textContent='Could not read that logo.';return}}
    // Keep previous bill IDs and any unrecognized fields to preserve compatibility.
    const updated={...(b||{}),id:b?.id||(crypto.randomUUID?crypto.randomUUID():String(Date.now())),name,date,day:Number(date.slice(-2)),frequency,amount:money(amount),category};
    if(b)data.bills[i]=updated;else data.bills.push(updated);
    if(logo){data.subLogos??={};data.subLogos[name]=logo}
    save();render();billsEditor();
  };
}

